#include <cassert>
#include <cstdio>
#include <cmath>
#include "competition_actuators.h"
int main(){using namespace competition_shadow;ServoTuning t{};assert(ServoMapper::valid(t));ServoMapper m(t);assert(m.map(0,.02f).pulseUs==1500);assert(m.map(1,.02f).pulseUs==1502);for(int i=0;i<30;++i)m.map(1,.02f);assert(m.previousPulseUs()==1520);assert(m.map(100,.02f).clamped);assert(!m.map(NAN,.02f).finite);t.reversed=true;ServoMapper r(t);for(int i=0;i<3;++i)r.map(1,.10f);assert(r.previousPulseUs()==1480);DutyRamp ramp(.03f,.5f,.5f);ramp.setTarget(.03f);for(int i=0;i<25;++i)ramp.step(.02f);assert(fabsf(ramp.applied()-.03f)<.00001f);ramp.setTarget(0);for(int i=0;i<25;++i)ramp.step(.02f);assert(fabsf(ramp.applied())<.00001f);ramp.stopImmediate();assert(ramp.applied()==0);std::puts("COMPETITION_ACTUATORS_HOST_PASS narrow_limits=ok rate_limit=ok reverse=ok duty_ramp=ok");}